// ---- build a 64-entry high-contrast palette LUT once/frame (hue-rotatable) ----
function h2r(h,s,v){h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,xx=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,bl;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=xx;bl=0;}else if(sg===1){r=xx;g=c;bl=0;}else if(sg===2){r=0;g=c;bl=xx;}else if(sg===3){r=0;g=xx;bl=c;}else if(sg===4){r=xx;g=0;bl=c;}else{r=c;g=0;bl=xx;}return [(r+m)*255,(g+m)*255,(bl+m)*255];}
